// ─── File: MultiTenantDemo.java ───
// Multi-tenancy: resolve tenant from token, isolate data, per-tenant limits.
package com.bank.gateway.demo;

import java.util.logging.*;

public class MultiTenantDemo {
    private static final Logger log = Logger.getLogger("MultiTenant");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new MtLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MultiTenantGateway gateway = new MultiTenantGateway();

        log.info("=== Premium tenant request ===");
        gateway.handle(new TenantRequest("token:partner-premium", "partner-premium", "/api/v1/accounts"));

        log.info("=== Basic tenant request (different datasource) ===");
        gateway.handle(new TenantRequest("token:partner-basic", "partner-basic", "/api/v1/accounts"));

        log.info("=== Spoof attempt: header says premium, token says basic ===");
        gateway.handle(new TenantRequest("token:partner-basic", "partner-premium", "/api/v1/accounts"));

        log.info("=== Basic tenant floods — its own limit trips, premium unaffected ===");
        for (int i = 0; i < 4; i++)
            gateway.handle(new TenantRequest("token:partner-basic", "partner-basic", "/api/v1/accounts"));
        log.info("=== Premium still works during basic's flood ===");
        gateway.handle(new TenantRequest("token:partner-premium", "partner-premium", "/api/v1/accounts"));
    }
}

// ─── Would be in core/TenantRequest.java ───
class TenantRequest {
    final String token; final String headerTenant; final String path;
    TenantRequest(String token, String headerTenant, String path) {
        this.token = token; this.headerTenant = headerTenant; this.path = path;
    }
}

// ─── Would be in tenant/TenantResolver.java ───
class TenantResolver {
    // token format for demo: "token:<tenantId>"; the tenant comes from the SIGNED token.
    String fromToken(String token) {
        if (token == null || !token.startsWith("token:")) return null;
        return token.substring("token:".length());
    }
    // reject if a client-supplied header disagrees with the trusted token tenant.
    boolean headerMatchesToken(String headerTenant, String tokenTenant) {
        return headerTenant == null || headerTenant.equals(tokenTenant);
    }
}

// ─── Would be in tenant/TenantPlanRegistry.java ───
class TenantPlanRegistry {
    static class Plan { final String name; final int rateLimit; final String datasource;
        Plan(String name, int rateLimit, String datasource) { this.name = name; this.rateLimit = rateLimit; this.datasource = datasource; } }
    private final java.util.Map<String, Plan> plans = new java.util.HashMap<>();
    TenantPlanRegistry() {
        plans.put("partner-premium", new Plan("PREMIUM", 5, "premiumdb"));
        plans.put("partner-basic",   new Plan("BASIC",   2, "shareddb[schema=basic]"));
    }
    Plan planFor(String tenant) { return plans.get(tenant); }
}

// ─── Would be in tenant/RateLimiter.java ───
class RateLimiter {
    private final java.util.Map<String, Integer> counts = new java.util.HashMap<>();
    // per-tenant counter: one tenant's flood cannot consume another's budget.
    boolean allow(String tenant, int limit) {
        int c = counts.merge(tenant, 1, Integer::sum);
        return c <= limit;
    }
}

// ─── Would be in tenant/TenantDataRouter.java ───
class TenantDataRouter {
    // select the correct isolated datasource for the tenant.
    String datasourceFor(TenantPlanRegistry.Plan plan) { return plan.datasource; }
}

// ─── Would be in core/MultiTenantGateway.java ───
class MultiTenantGateway {
    private static final Logger log = Logger.getLogger("MultiTenant");
    private final TenantResolver resolver = new TenantResolver();
    private final TenantPlanRegistry registry = new TenantPlanRegistry();
    private final RateLimiter limiter = new RateLimiter();
    private final TenantDataRouter router = new TenantDataRouter();

    String handle(TenantRequest req) {
        // 1) resolve tenant from the SIGNED token (never trust the header alone).
        String tenant = resolver.fromToken(req.token);
        if (tenant == null) { log.severe("REJECT: no tenant in token"); return "401"; } // fail closed
        // 2) reject spoof: header must not contradict the token.
        if (!resolver.headerMatchesToken(req.headerTenant, tenant)) {
            log.severe(() -> "REJECT: tenant spoof header=" + req.headerTenant + " token=" + tenant);
            return "403-spoof";
        }
        TenantPlanRegistry.Plan plan = registry.planFor(tenant);
        if (plan == null) { log.severe("REJECT: unknown tenant"); return "403"; }
        // 3) per-tenant rate limit (noisy-neighbor isolation).
        if (!limiter.allow(tenant, plan.rateLimit)) {
            log.warning(() -> "429 rate limit for tenant=" + tenant + " (plan " + plan.name + ")");
            return "429";
        }
        // 4) data isolation: route to the tenant's own datasource.
        String ds = router.datasourceFor(plan);
        log.info(() -> "ALLOW tenant=" + tenant + " plan=" + plan.name + " → datasource=" + ds
                + " (propagate X-Tenant-Id downstream)");
        return "200-ok[" + tenant + "]";
    }
}

